import { createHmac, pbkdf2Sync } from 'node:crypto';
import { readFileSync } from 'node:fs';

// Generated by Rails 7.2 using the app's Rails 7.0 defaults and a dummy key.
export const fixture = JSON.parse(readFileSync(new URL('./fixtures/rails-token.json', import.meta.url)));
const key = pbkdf2Sync(fixture.secretKeyBase, 'e621_media', 1000, 64, 'sha256');

export function sign(source, { purpose = 'e621_media', expires = null, serialized } = {}) {
  const data = Buffer.from(source);
  const marshal = serialized || Buffer.concat([
    Buffer.from([4, 8, 0x49, 0x22, data.length + 5]), data, Buffer.from([6, 0x3a, 6, 0x45, 0x54]),
  ]);
  const payload = Buffer.from(JSON.stringify({
    _rails: { message: marshal.toString('base64'), exp: expires, pur: purpose },
  })).toString('base64');
  return `${payload}--${createHmac('sha1', key).update(payload).digest('hex')}`;
}
